import type { RequestHandler } from './$types';
import type { Varchar } from '@prisma/orm-postgres/target/codec-types';

import { maskPhone, normalizePhone } from '#lib/phone';
import { errorResponse } from '#lib/server/api';
import { forbiddenRole, ROLE_QUAN_LY, unauthenticated } from '#lib/server/auth';
import type { Customer, CustomerCreated } from '#lib/types/customer';
import { db } from '../../../prisma/db';

export const GET: RequestHandler = async ({ url, locals }) => {
  const employee = locals.employee;
  if (!employee) return unauthenticated();

  const raw = url.searchParams.get('phone') ?? '';
  const phone = normalizePhone(raw);
  if (!phone) {
    return errorResponse(
      400,
      'INVALID_PHONE',
      'Số điện thoại phải gồm đúng 10 chữ số (dạng 0xxxxxxxxx)',
      { phone: raw },
    );
  }

  const customer = await db.orm.public.Customer
    .where({ phone: phone as Varchar<20> })
    .select('customerId', 'phone', 'fullName', 'address')
    .first();

  if (!customer) {
    return errorResponse(404, 'CUSTOMER_NOT_FOUND', 'Không tìm thấy thông tin khách hàng');
  }

  const devices = await db.orm.public.Device
    .where({ customerId: customer.customerId })
    .select('deviceId', 'serialNo', 'isExternal', 'purchaseDate', 'warrantyMonths')
    .all();

  const body: Customer = {
    customer_id: Number(customer.customerId),
    full_name: customer.fullName,
    phone_masked: maskPhone(customer.phone),
    address: customer.address,
    devices: devices.map((device) => ({
      device_id: Number(device.deviceId),
      serial_no: device.serialNo,
      is_external: device.isExternal,
      purchase_date: device.purchaseDate,
      warranty_months: device.warrantyMonths,
    })),
  };

  if (employee.role === ROLE_QUAN_LY) {
    body.phone = customer.phone;
  }

  return Response.json(body);
};

export const POST: RequestHandler = async ({ request, locals }) => {
  const employee = locals.employee;
  if (!employee) return unauthenticated();
  if (employee.role === ROLE_QUAN_LY) return forbiddenRole();

  const body = (await request.json().catch(() => null)) as {
    phone?: string;
    full_name?: string;
    address?: string;
  } | null;

  const fullName = (body?.full_name ?? '').trim();
  if (!fullName) {
    return errorResponse(400, 'VALIDATION_FAILED', 'Vui lòng nhập Họ tên khách hàng', {
      full_name: 'Trường bắt buộc',
    });
  }

  const raw = (body?.phone ?? '').trim();
  const phone = normalizePhone(raw);
  if (!phone) {
    return errorResponse(
      400,
      'INVALID_PHONE',
      'Số điện thoại phải gồm đúng 10 chữ số (dạng 0xxxxxxxxx)',
      { phone: raw },
    );
  }

  const existing = await db.orm.public.Customer
    .where({ phone: phone as Varchar<20> })
    .select('customerId')
    .first();

  if (existing) {
    return errorResponse(409, 'CUSTOMER_EXISTS', 'Số điện thoại đã tồn tại trên hệ thống', {
      existing_customer_id: Number(existing.customerId),
    });
  }

  const address = (body?.address ?? '').trim();

  const created = await db.orm.public.Customer.create({
    phone: phone as Varchar<20>,
    fullName: fullName as Varchar<120>,
    address: address ? (address as Varchar<255>) : null,
    isActive: true,
  });

  return Response.json(
    {
      customer_id: Number(created.customerId),
      full_name: created.fullName,
      phone_masked: maskPhone(created.phone),
    } satisfies CustomerCreated,
    { status: 201 },
  );
};
